signature.code:
// static
createResourceHooks(config) => { useResource(), useField, useFieldArray, destroy }

// dynamic
createResourceHooks((params: P) => config) => { useResource(params), useField, useFieldArray, destroy }

examples.code:
export const { useResource, useField } = createResourceHooks({
  initialData: { name: '' },
  source: { save: (d) => api.save(d) },
});

// useResource(); useField('name');

export const { useResource, useField, useFieldArray } =
  createResourceHooks((productId: string) => ({
    key: ['product', productId],
    persist: { draft: true },
    source: {
      fetch: () => api.getProduct(productId),
      save: (d) => api.updateProduct(productId, d),
    },
  }));

function Editor({ productId }) {
  const { save, isChanged } = useResource(productId);
  return (
    <>
      <Name />
      <button disabled={!isChanged} onClick={() => save()}>Save</button>
    </>
  );
}

function Name() {
  const { value, onChange, onBlur } = useField('name');
  return <input value={value ?? ''} onChange={(e) => onChange(e.target.value)} onBlur={onBlur} />;
}
